def ad_text(card):
    """Готовое объявление для OLX, Instagram и Telegram-канала."""
    title = " ".join(str(x) for x in (card.get("brand"), card.get("model"),
                                      card.get("year")) if x)
    L = ["%s" % title]
    L.append("Цена: %s" % S.money(_int(card.get("price_uah"))))
    L.append("")
    tech = []
    if card.get("engine_cc"):
        tech.append("%s, %s" % (S.num(_int(card.get("engine_cc")), " см³"),
                                card.get("fuel") or ""))
    if card.get("gearbox"):
        tech.append(card["gearbox"])
    if card.get("drive"):
        tech.append("привод %s" % card["drive"])
    if card.get("mileage_km"):
        tech.append("пробег %s" % S.num(_int(card.get("mileage_km")), " км"))
    if card.get("color"):
        tech.append(card["color"])
    L.append(" · ".join(t for t in tech if t))
    if card.get("condition_text"):
        L.append("")
        L.append(card["condition_text"])

    left, eta = eta_of(card)
    L.append("")
    if left is not None:
        L.append("В Киеве через %d дней, ориентировочно %s."
                 % (left, eta.strftime("%d.%m.%Y")))
    else:
        L.append("Статус: %s" % S.status_label(card.get("status")))

    L.append("")
    L.append("Автомобиль из Кореи под ключ: подбор, договор, выкуп на аукционе,")
    L.append("доставка, растаможка, доставка до Киева и сертификат — всё в цене.")
    L.append("Цена фиксируется в договоре и не меняется.")
    L.append("")
    L.append("UA Art Company LLC · Киев, ул. Победы 20")
    L.append("[N]")
    return "\n".join(L)


