def _ubrat_fayly_video(nomer):
    """Ролики машины и их заставки с диска."""
    import glob as _g
    import json as _j
    ubrano = 0
    nom = str(nomer or "").upper()
    if not nom:
        return 0
    papka = os.path.join("/home/Carix", "video")
    puti = (_g.glob(os.path.join(papka, "%s.mp4" % nom))
            + _g.glob(os.path.join(papka, "%s-*.mp4" % nom)))
    for put in puti:
        try:
            os.remove(put)
            ubrano += 1
        except Exception:
            pass
        try:
            if os.path.exists(put + ".poster.jpg"):
                os.remove(put + ".poster.jpg")
        except Exception:
            pass
    try:
        pamyat = "/home/Carix/.video_sinhron.json"
        d = _j.load(open(pamyat, encoding="utf-8"))
        if nom in d:
            d.pop(nom)
            with open(pamyat, "w", encoding="utf-8") as f:
                _j.dump(d, f, ensure_ascii=False)
    except Exception:
        pass
    return ubrano


